    public static class NavigationTokens
    {
        public static readonly ControlTokenIdentity Identity = new ControlTokenIdentity("MaterialGallery", "Navigation");
    }

    public class NavigationTokenResourceExtension : TokenResourceExtension<NavigationTokenKey>
    {
        public NavigationTokenResourceExtension()
        {
        }

        public NavigationTokenResourceExtension(NavigationTokenKey kind)
            : base(kind)
        {
        }

        protected override object GetResourceKey(NavigationTokenKey kind)
        {
            var slot = (int)kind;
            if (slot >= 0)
            {
                if ((uint)slot >= 255u)
                {
                    throw new global::System.ArgumentOutOfRangeException(nameof(kind));
                }
                return ControlTokenResourceKey.Global(NavigationTokens.Identity, (SharedTokenKind)slot);
            }
            var ownSlot = -1 - slot;
            if ((uint)ownSlot < 1u)
            {
                return (NavigationTokenKind)ownSlot;
            }
            throw new global::System.ArgumentOutOfRangeException(nameof(kind));
        }
    }

